<script>(()=>{const nav=document.querySelector('[data-s602-nav]');document.querySelector('[data-s602-menu]')?.addEventListener('click',()=>nav?.classList.toggle('is-open'));document.querySelectorAll('[data-s602-slider]').forEach(slider=>{const slides=[...slider.querySelectorAll('[data-s602-slide]')];if(slides.length<2)return;let i=0;const show=n=>{slides[i].classList.remove('is-active');i=(n+slides.length)%slides.length;slides[i].classList.add('is-active')};slider.querySelector('[data-s602-prev]')?.addEventListener('click',()=>show(i-1));slider.querySelector('[data-s602-next]')?.addEventListener('click',()=>show(i+1));setInterval(()=>show(i+1),Math.max(2500,Number(slider.dataset.autoplay||5600)))});document.querySelectorAll('[data-s602-strip]').forEach(strip=>{const track=strip.querySelector('[data-s602-strip-track]');const cards=[...track.children];if(cards.length<2)return;let i=0;setInterval(()=>{const visible=innerWidth<601?1:innerWidth<901?2:innerWidth<1201?3:4;i=(i+1)%Math.max(1,cards.length-visible+1);track.style.transform=`translateX(-${i*(100/visible)}%)`},Math.max(2500,Number(strip.dataset.autoplay||3600)))});document.querySelectorAll('[data-s602-countdown]').forEach(node=>{const end=new Date(node.dataset.s602Countdown||Date.now()+604800000);const tick=()=>{const d=Math.max(0,end-Date.now()),days=Math.floor(d/86400000),hours=Math.floor(d/3600000)%24,mins=Math.floor(d/60000)%60,secs=Math.floor(d/1000)%60;node.textContent=[days,hours,mins,secs].map(x=>String(x).padStart(2,'0')).join('   ')};tick();setInterval(tick,1000)})})();</script>
